 const safe=toggle('shortsFramingSafeArea','자막을 유튜브 버튼·하단 정보 영역 위에 배치',true),replace=toggle('shortsFramingReplaceManual','직접 정한 기존 구도도 새 제안으로 바꾸기',false);body.append(safe.wrapper,replace.wrapper);
 const actions=node('div','production-actions'),preview=button('prepareShortsFramingBtn','세로 구도 미리보기'),analyze=button('analyzeShortsFramingBtn','AI로 피사체 구도 분석','primary'),cancel=button('cancelShortsFramingBtn','작업 취소'),configure=button('shortsFramingApiSettingsBtn','API 설정','ghost');cancel.hidden=true;actions.append(preview,analyze,cancel,configure);body.append(actions);
 const count=node('p','production-help');count.id='shortsFramingCount';const status=node('p','production-status');status.id='shortsFramingStatus';status.setAttribute('role','status');const error=node('p','production-error');error.id='shortsFramingError';error.setAttribute('role','alert');body.append(count,status,error);
 const progress=createOperationStatus({container:body,region:body,id:'shortsFramingOperation'}),grid=node('div','shorts-framing-grid');grid.id='shortsFramingGrid';body.append(grid);
